//! Genuine child Window EventTarget methods resolve through their owner prototypes.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->Value{p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=main>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://child-methods.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,owner=child.document,target=owner.body,calls=0;function callback(){calls++;}document.body;");(d,f,p)}
#[test]
fn event_child_methods_direct_reads_have_canonical_owner_identity_and_real_native_delivery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var proto=child.EventTarget.prototype;for(var method of ['addEventListener','removeEventListener','dispatchEvent']){var fn=child[method];if(fn!==proto[method]||fn!==child[method]||Object.getPrototypeOf(fn)!==child.Function.prototype||fn===EventTarget.prototype[method]||fn.name!==method||fn.length!==(method==='dispatchEvent'?1:2))throw 'canonical method owner';}child.addEventListener('check',callback);child.addEventListener('check',callback);if(!child.dispatchEvent(new child.Event('check'))||calls!==1)throw 'actual Window dispatch';child.removeEventListener('check',callback);child.dispatchEvent(new Event('check'));if(calls!==1)throw 'actual Window removal';var add=child.addEventListener,dispatch=child.dispatchEvent,remove=child.removeEventListener;for(var node of [document.body,owner,target]){add.call(node,'borrow',callback);dispatch.call(node,new Event('borrow'));remove.call(node,'borrow',callback);}if(calls!==4)throw 'same-origin canonical receiver borrowing';
"#);assert!(p.state.listeners.is_empty());assert!(p.state.synthetic_dispatches.is_empty());}
#[test]
fn event_child_methods_prototype_overrides_deletion_and_getter_receivers_remain_ordinary(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var proto=child.EventTarget.prototype,original=Object.getOwnPropertyDescriptor(proto,'dispatchEvent'),getterCalls=0;Object.defineProperty(proto,'dispatchEvent',{configurable:true,enumerable:true,get:function(){if(this!==child)throw 'child getter receiver';getterCalls++;return function(){return this===child?'override':'wrong';};}});if(child.dispatchEvent()!=='override'||getterCalls!==1)throw 'ordinary inherited getter';delete proto.dispatchEvent;if(typeof child.dispatchEvent!=='undefined')throw 'deleted method resurrected';Object.defineProperty(proto,'dispatchEvent',original);if(child.dispatchEvent!==original.value)throw 'restored canonical identity';Object.defineProperty(child.Window.prototype,'addEventListener',{configurable:true,value:function(){return this===child?'nearer':'wrong';}});if(child.addEventListener()!=='nearer')throw 'Window prototype override';delete child.Window.prototype.addEventListener;if(child.addEventListener!==proto.addEventListener)throw 'restored ancestry';if(window.addEventListener===child.addEventListener||EventTarget.prototype.dispatchEvent===child.dispatchEvent)throw 'main realm isolation';
"#);}
#[test]
fn event_child_methods_saved_bound_and_property_reads_preserve_original_origin_and_connection(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var savedAdd=child.addEventListener,savedRemove=child.removeEventListener,savedDispatch=child.dispatchEvent,bound=savedDispatch.bind(child),event=new child.Event('check'),effects=0,arg={toString:function(){effects++;return 'check';}},options={get capture(){effects++;return false;}};child.addEventListener('check',callback);Object.defineProperty(child.Window.prototype,'probe',{configurable:true,get:function(){effects++;return 1;}});
"#);let count=p.state.listeners.len();p.set_location(&crate::navigation::address("https://other.test/source",&crate::navigation::Location::home()).unwrap());for source in ["child.addEventListener","child.removeEventListener","child.dispatchEvent","savedAdd.call(child,arg,callback,options)","savedRemove.call(child,arg,callback,options)","bound(event)"]{p.begin_job();let error=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!(p.state.listeners.len(),count);assert!(p.state.synthetic_dispatches.is_empty());}p.set_location(&crate::navigation::address("https://child-methods.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"if(effects||calls)throw 'origin refusal prefix';child.dispatchEvent(event);if(calls!==1)throw 'origin recovery';frame.remove();");p.begin_job();let before=(p.state.retained,p.state.listeners.len());let error=p.runtime.execute("bound(event)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("teardown")||error.contains("connected"),"{error}");assert_eq!((p.state.retained,p.state.listeners.len()),before);assert!(p.state.synthetic_dispatches.is_empty());run(&mut d,&mut f,&mut p,"var fresh=document.createElement('iframe');fresh.hidden=true;document.body.appendChild(fresh);var freshChild=fresh.contentWindow;if(freshChild===child)throw 'fresh Window identity';freshChild.addEventListener('check',callback);freshChild.dispatchEvent(new Event('check'));if(calls!==2)throw 'fresh connected recovery';");}
#[test]
fn event_child_methods_raw_types_nested_object_once_abort_and_target_only_path_are_real(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var type='\ud800\u0000\udfff',log='',controller=new AbortController(),listener={handleEvent:function(e){if(this!==listener||e.type!==type||e.target!==child||e.currentTarget!==child||e.eventPhase!==2||e.composedPath().length!==1||e.composedPath()[0]!==child||e.isTrusted)throw 'child object callback';log+='O';e.preventDefault();}};child.addEventListener(type,listener,{once:true});child.addEventListener(type,function(){controller.abort();child.dispatchEvent(new child.Event('nested'));log+='T';},{once:true});child.addEventListener(type,function(){throw 'aborted Window registration';},{signal:controller.signal});child.addEventListener('nested',function(){log+='I';});var event=new child.CustomEvent(type,{cancelable:true,detail:target});if(child.dispatchEvent(event)!==false||log!=='OIT'||event.detail!==target||event.currentTarget!==null||event.eventPhase||event.composedPath().length)throw 'child native dispatch cleanup';child.dispatchEvent(new Event(type));if(log!=='OIT')throw 'once cleanup';
"#);assert!(p.state.synthetic_dispatches.is_empty());}
#[test]
fn event_child_methods_checked_direct_operations_refuse_without_prefix_and_recover(){
 for operation in 0..3{for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var event=new child.Event('check');child.addEventListener('check',callback);child.removeEventListener;child.dispatchEvent;");let before=(p.state.retained,p.state.listeners.len());let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}let source=match operation{0=>"child.dispatchEvent(event)",1=>"child.addEventListener('new',callback)",_=>"child.removeEventListener('check',callback)"};let result=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state});if operation==2&&profile==2{assert!(result.is_ok());assert_eq!(p.state.listeners.len(),before.1-1);}else{assert!(result.is_err(),"operation{operation}profile{profile}");assert_eq!((p.state.retained,p.state.listeners.len()),before);}assert!(p.state.synthetic_dispatches.is_empty());p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(calls)throw 'refused callback prefix';child.removeEventListener('check',callback);child.addEventListener('check',callback);child.dispatchEvent(event);if(calls!==1)throw 'direct method recovery';");}}
}
